-- Subcategorías y SEO de categorías (14-10-2026). Ya aplicado en Supabase.
-- Copias previas: products_categoria_backup_20261014 y categories_seo_backup_20261014.
-- Para deshacer la clasificación: update products p set category=b.category, subcategory=b.subcategory from products_categoria_backup_20261014 b where b.id=p.id;

alter table public.categories add column if not exists h1 varchar(120);
alter table public.categories add column if not exists intro text;

create table if not exists public.subcategories (
  id uuid primary key default gen_random_uuid(),
  category_id uuid not null references public.categories(id) on delete cascade,
  name varchar(120) not null,
  slug varchar(120) not null,
  h1 varchar(120),
  intro text,
  seo_title varchar(120),
  seo_description text,
  has_page boolean not null default true,
  display_order integer not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (category_id, slug),
  unique (category_id, name)
);
create index if not exists subcategories_category_idx on public.subcategories(category_id);
alter table public.subcategories enable row level security;
create policy "Public read active subcategories" on public.subcategories for select using (is_active = true);
create policy "Admin read all subcategories" on public.subcategories for select using (is_admin());
create policy "Admin insert subcategories" on public.subcategories for insert with check (is_admin());
create policy "Admin update subcategories" on public.subcategories for update using (is_admin()) with check (is_admin());
create policy "Admin delete subcategories" on public.subcategories for delete using (is_admin());
create index if not exists products_category_subcategory_idx on public.products(category, subcategory);

update public.categories c set h1=v.h1, seo_title=v.t, seo_description=coalesce(v.d,c.seo_description), intro=v.i, updated_at=now() from (values
('smart-home',$q$Domótica para casa: luces, enchufes y termostatos inteligentes$q$,$q$Domótica para casa: luces, enchufes y clima$q$,$q$Bombillas, enchufes, termostatos y asistentes con Alexa: cuáles piden hub, cuáles funcionan con Matter y qué sigue funcionando si se cae internet.$q$,$q$La domótica para casa empieza casi siempre por algo pequeño: una bombilla que se enciende con la voz, un enchufe que apaga el calefactor a una hora o un termostato que baja la calefacción cuando no hay nadie. Aquí reunimos esos aparatos y los comparamos por lo que de verdad complica la vida después de comprarlos.

Antes de elegir, mira tres cosas. La primera, cómo se conecta: el WiFi no necesita nada más, pero Zigbee y Thread piden un hub o un altavoz que haga de puente. La segunda, con qué ecosistema habla: Alexa, Google Home, HomeKit o Matter, el estándar que intenta que todo funcione con todo. La tercera, qué pasa sin internet: hay dispositivos que siguen obedeciendo en local y otros que se quedan mudos.

Si vas a empezar, la iluminación y los enchufes son lo más sencillo. Los termostatos son lo que más se nota en la factura, pero conviene revisar antes si tu caldera o tus radiadores son compatibles.$q$),
('baterias-y-energia',$q$Estaciones de energía portátiles, power banks y paneles solares$q$,$q$Estaciones de energía y power banks$q$,null,$q$Una estación de energía portátil es una batería grande con enchufes de 230 V, USB y a veces salida de coche, pensada para acampar, trabajar fuera o aguantar un apagón en casa. Un power bank es su hermano pequeño: carga el móvil, la tableta o el portátil por USB. Y los paneles solares sirven para recargar cualquiera de los dos sin red eléctrica.

La cifra que manda es la capacidad en vatios hora (Wh), no la potencia. Con 300 Wh mueves un portátil durante una jornada de trabajo; con 1.000 Wh aguantas una nevera varias horas. La potencia de salida (W) solo dice qué aparato puedes enchufar, no cuánto dura. En los power banks pasa algo parecido con los mAh: para un portátil, lo que importa es que dé 45, 65 o 100 W por USB-C.

Fíjate también en la química de la batería. Las LiFePO4 aguantan miles de ciclos y son más seguras; las de ion-litio pesan menos. Y si quieres usarla como SAI, comprueba el tiempo de conmutación.$q$),
('almacenamiento',$q$NAS, discos duros y SSD para casa$q$,$q$NAS para casa, discos duros y SSD$q$,null,$q$Almacenamiento para casa quiere decir tres cosas distintas. Un NAS es un pequeño servidor que se conecta al router y guarda las fotos, las copias de seguridad y las películas de toda la familia en un solo sitio. Un disco duro externo es la opción sencilla para llevar archivos de un ordenador a otro o hacer una copia de vez en cuando. Y un SSD es lo que hace que un ordenador viejo arranque en segundos.

En un NAS, lo primero son las bahías: con una tienes espacio; con dos ya puedes duplicar los datos (RAID 1) por si se rompe un disco. Después, el procesador y la RAM, que deciden si podrá con Plex, Docker o máquinas virtuales. Y los discos: para un NAS conviene usar modelos CMR pensados para funcionar las 24 horas, no los de sobremesa.

En los SSD, mira el formato (SATA de 2,5 pulgadas o M.2 NVMe), si lleva DRAM y cuánto rinde cuando se acaba la caché, que es donde los baratos se quedan cortos.$q$),
('proyectores',$q$Proyectores para casa: 4K, Full HD y portátiles$q$,$q$Proyectores para casa: 4K, Full HD y mini$q$,null,$q$Un proyector para casa convierte una pared en una pantalla de 100 pulgadas o más por mucho menos de lo que cuesta una tele de ese tamaño. Aquí tienes desde mini proyectores para ver series en el dormitorio hasta modelos 4K para montar un cine en el salón, junto con las pantallas para proyectar encima.

El dato que más engaña es el brillo. Muchos fabricantes anuncian «lúmenes» sin más, y la cifra que sirve es la de lúmenes ANSI o ISO. Por debajo de 300 lúmenes ANSI necesitas oscuridad total; a partir de 1.500 ya se ve bien con algo de luz. La resolución nativa importa más que el «compatible con 4K» de la caja: muchos aceptan señal 4K pero la muestran en 1080p.

Revisa también la distancia de proyección, el ruido del ventilador y qué sistema lleva para las apps: no todos tienen Netflix oficial.$q$),
('streaming',$q$Equipo para streaming: webcams, micrófonos y capturadoras$q$,$q$Webcams, micrófonos y capturadoras$q$,null,$q$El equipo para hacer streaming o grabar vídeos desde casa se resume en tres piezas: una webcam que se vea bien con la luz de una habitación normal, un micrófono que no capte el teclado y, si juegas en consola, una capturadora que pase la imagen al ordenador.

En las webcams, la resolución dice poco por sí sola. Importan más el sensor, el enfoque automático y cómo se comporta con poca luz: una buena 1080p a 60 fps se ve mejor que una 4K mediocre. En los micrófonos, los USB son lo más fácil para empezar, los dinámicos rechazan mejor el ruido de fondo y los inalámbricos de solapa son los cómodos para grabar con el móvil.

En las capturadoras, fíjate en si tienen passthrough, para jugar sin retraso mientras grabas, y en qué resolución capturan de verdad, que no siempre es la que pasan a la tele. Aquí también encontrarás los reproductores Fire TV.$q$),
('escaner',$q$Escáneres de documentos, fotos y negativos$q$,$q$Escáneres de documentos, fotos y negativos$q$,$q$Escáneres portátiles, planos y de negativos comparados por resolución útil, velocidad por página y si funcionan sin instalar nada en el ordenador.$q$,$q$Elegir escáner depende de lo que quieras digitalizar. Para documentos sueltos y facturas, un escáner portátil o uno con alimentador hace el trabajo en segundos. Para fotos en papel y libros, un escáner plano da mejor calidad. Y para negativos y diapositivas hace falta un aparato con luz propia, porque un escáner plano normal no puede leer la película.

La resolución anunciada sirve de poco: para documentos bastan 300 ppp y para fotos en papel, 600. Donde sí se nota es en los negativos, que necesitan 2.400 ppp o más para sacar una copia decente. Fíjate también en si escanea a doble cara de una pasada, si se conecta por WiFi y si funciona con el software del sistema o te obliga a instalar el del fabricante.

Abajo tienes los escáneres ordenados por tipo y, al final, las guías para elegir el tuyo.$q$),
('seguridad-inteligente',$q$Seguridad para casa: sensores, alarmas y cámaras WiFi$q$,$q$Alarmas, sensores y cámaras WiFi para casa$q$,null,$q$La seguridad inteligente para casa permite montar una alarma sencilla sin pagar cuotas: sensores en puertas y ventanas, detectores de movimiento, cámaras WiFi y cerraduras que avisan al móvil cuando pasa algo.

Lo primero que hay que mirar es si el aparato necesita hub. Los sensores WiFi se conectan directamente al router pero gastan más pila; los Zigbee, Thread o Matter duran más y responden antes, a cambio de un puente. En las cámaras, comprueba si graban en local (tarjeta microSD o NAS) o solo en la nube con suscripción, y qué funciones se pierden si no pagas.

Ninguno de estos aparatos sustituye a una alarma conectada a una central receptora, pero para saber qué pasa en casa cuando no estás son una buena primera capa.$q$),
('cultivo-inteligente',$q$Huertos hidropónicos, lámparas de cultivo y riego automático$q$,$q$Huertos hidropónicos y riego automático$q$,$q$Huertos de interior con LED, lámparas de cultivo y riego automático: qué consume cada uno, cuántas plantas caben y cuáles atan a recambios de marca.$q$,$q$El cultivo inteligente sirve para tener hierbas, lechugas o tomates cherry en casa sin depender del tiempo ni de acordarte de regar. Aquí juntamos tres tipos de aparatos: huertos hidropónicos de interior, que lo traen todo; lámparas LED de cultivo, para las plantas que ya tienes; y sistemas de riego automático, para macetas, balcones y jardín.

En los huertos hidropónicos, cuenta las vainas que necesitas de verdad y mira si admiten semillas propias o solo cápsulas de la marca. La altura máxima de la lámpara marca qué puedes cultivar. En las lámparas de cultivo, los vatios reales y el espectro importan más que el número de LED. Y en el riego, decide entre goteo con bomba, que no necesita grifo, o programador de grifo, y comprueba si funciona con poca presión.$q$),
('impresoras-de-etiquetas',$q$Impresoras de etiquetas y etiquetadoras$q$,$q$Impresoras de etiquetas y etiquetadoras$q$,null,$q$Una impresora de etiquetas sirve para cosas muy distintas: rotular cables y tarros en casa, imprimir etiquetas de envío para una tienda online o sacar códigos de barras para un almacén. Por eso las separamos en etiquetadoras Bluetooth que se manejan desde el móvil, rotuladoras con teclado, impresoras de etiquetas de envío de 4x6 pulgadas e impresoras de sobremesa para la oficina.

Casi todas son térmicas: no usan tinta, pero sí etiquetas de papel térmico, y ahí está el gasto de verdad. Antes de comprar, mira si aceptan rollos genéricos o solo los de la marca, qué anchos admiten y si el programa deja diseñar desde el ordenador. Para envíos, comprueba que imprime el formato que piden tus transportistas y que funciona con tu plataforma de venta.$q$),
('conectividad-docking',$q$Hubs USB-C, docking stations y HDMI inalámbrico$q$,$q$Hubs USB-C, docks y HDMI inalámbrico$q$,$q$Hubs y bases USB-C para portátil y transmisores HDMI inalámbricos: si dan 4K a 60 Hz, cuánta carga pasa de verdad y con qué ordenadores funcionan.$q$,$q$Los portátiles actuales traen pocos puertos, y un hub USB-C o una docking station los recupera: HDMI para el monitor, USB para el teclado y el ratón, Ethernet y carga, todo con un solo cable. Aquí también tienes transmisores HDMI inalámbricos, que llevan la imagen del ordenador o la consola a la tele o al proyector sin cable.

Lo que más falla en los hubs es el vídeo. Muchos anuncian 4K pero solo a 30 Hz, y se nota al mover el ratón. En los MacBook con chip M1, M2 o M3 básico, un hub con dos HDMI muestra la misma imagen en las dos pantallas: para extender hace falta DisplayLink. Revisa también cuántos vatios de carga deja pasar al portátil. En los transmisores inalámbricos, la distancia real y el retraso deciden si sirven para jugar o solo para presentaciones.$q$),
('realidad-virtual',$q$Gafas de realidad virtual y accesorios$q$,$q$Gafas de realidad virtual y accesorios VR$q$,$q$Gafas Meta Quest, PlayStation VR2 y visores para móvil, y los accesorios que de verdad mejoran la comodidad en las sesiones largas.$q$,$q$Las gafas de realidad virtual se dividen hoy en tres grupos. Las autónomas, como Meta Quest 3 y 3S, no necesitan ordenador ni cables. Las que dependen de una consola u ordenador, como PlayStation VR2, dan más calidad gráfica a cambio de estar atadas. Y los visores para móvil son la puerta de entrada más barata, pensados para vídeos 360 y para que los niños prueben la experiencia.

Antes de elegir, mira la resolución por ojo, si se puede ajustar la distancia entre lentes y el catálogo de juegos y apps de cada plataforma. La comodidad pesa tanto como las especificaciones: por eso incluimos fundas para los mandos y accesorios que hacen más agradables las sesiones largas.$q$),
('camara-instantanea',$q$Cámaras instantáneas Instax y Kodak$q$,$q$Cámaras instantáneas Instax y Kodak$q$,$q$Instax Mini 12, Instax Mini Evo y Kodak Mini Shot comparadas por lo que decide la compra: coste por copia, calidad del revelado y tamaño real de la foto.$q$,$q$Una cámara instantánea saca la foto y la imprime en el momento. Esa es la gracia y también el gasto: cada copia cuesta dinero, así que el precio de la película pesa tanto como el de la cámara.

Hay dos tecnologías. Las Instax de Fujifilm usan película química que se revela sola en unos minutos y da el aspecto clásico. Las Kodak Mini Shot imprimen por sublimación térmica, con cartuchos de tinta y papel, y dejan elegir qué foto imprimir. La Instax Mini Evo es un punto intermedio: una cámara digital con una impresora Instax dentro.

Fíjate en el tamaño de la copia (mini, square o wide), en si ajusta la exposición sola y en cuánto cuesta cada foto. Si ya tienes las fotos en el móvil y solo quieres imprimirlas, mira las impresoras de fotos portátiles.$q$),
('impresoras-portatiles',$q$Impresoras portátiles de fotos y térmicas$q$,$q$Impresoras portátiles de fotos y térmicas$q$,$q$Impresoras de bolsillo Zink, Instax Link y de 10x15, y térmicas sin tinta: calidad real de la copia, coste por hoja y qué consumible usa cada una.$q$,$q$Las impresoras portátiles imprimen desde el móvil por Bluetooth o WiFi y caben en una mochila. Hay dos familias muy distintas. Las de fotos imprimen en color: por sublimación (como Canon Selphy o Kodak), con papel Zink que no necesita tinta, o con película Instax. Las térmicas imprimen en blanco y negro sobre papel térmico, sin tinta, para notas, apuntes, pegatinas o documentos A4.

Lo que hay que comparar es el coste por copia y cuánto dura: el papel térmico se borra con el tiempo y el sol, mientras que la sublimación aguanta años. Mira también el tamaño de la copia, la batería y si la app obliga a crear una cuenta.$q$),
('papel',$q$Papel térmico para TPV y papel fotográfico$q$,$q$Papel térmico 80x80 y papel fotográfico$q$,null,$q$Aquí está el consumible que gastan otras categorías de la web: rollos de papel térmico para TPV, datáfonos e impresoras de bolsillo, y papel fotográfico para impresoras de tinta y portátiles.

En el papel térmico, la medida se da como ancho por diámetro del rollo: 80x80 es el estándar de las impresoras de tickets, y 57x35 o 57x40 el de los datáfonos. Comprueba siempre las dos cifras y busca rollos sin BPA, que en la Unión Europea está limitado en el papel térmico desde 2020. En el papel fotográfico, fíjate en el tamaño (10x15 es el habitual), el gramaje y el acabado brillo o mate, y en que sea compatible con tu impresora: el papel Zink, por ejemplo, solo sirve en impresoras Zink.$q$),
('ordenadores',$q$Mini PC para casa, oficina y teletrabajo$q$,$q$Mini PC para casa, oficina y teletrabajo$q$,null,$q$Un mini PC es un ordenador completo del tamaño de un libro pequeño que se atornilla detrás del monitor y consume una fracción de lo que gasta una torre. Para ofimática, navegar, videollamadas y teletrabajo es suficiente, y los modelos con Ryzen aguantan edición de fotos o juegos ligeros.

El procesador marca el nivel: los Intel N95, N100 y N150 están pensados para tareas básicas y para hacer de servidor doméstico; los Ryzen 5 y 7 rinden como un portátil de gama media. Mira después si la RAM es ampliable o va soldada, qué salidas de vídeo tiene para conectar dos o tres monitores y si trae Windows 11 con licencia. Si dudas entre procesadores, tienes la guía al final de la página.$q$),
('plotters',$q$Plotters A1 de impresión y plotters de corte$q$,$q$Plotters A1 y plotters de corte$q$,null,$q$Con el nombre de plotter se venden dos máquinas que no tienen nada que ver. El plotter de impresión es una impresora de gran formato que imprime planos, carteles y lonas en rollos de 24 pulgadas (A1) o más. El plotter de corte no imprime: corta vinilo, cartulina o tela siguiendo un dibujo, y es el que se usa para rotulación y manualidades.

En los de impresión, compara el ancho máximo, el coste de la tinta, el tiempo por plano A1 y si se conecta por WiFi. En los de corte, mira el ancho de material, la fuerza de corte y si el programa es gratuito o de suscripción.$q$),
('sistemas-de-alimentacion',$q$SAI para casa: router, NAS y ordenador$q$,$q$SAI para casa y estabilizadores de tensión$q$,null,$q$Un SAI (sistema de alimentación ininterrumpida, o UPS en inglés) es una batería que se pone entre el enchufe y tus aparatos y les da corriente unos minutos cuando se va la luz. En casa sirve para que el router siga funcionando, para que el NAS se apague bien y para no perder lo que estabas haciendo en el ordenador.

El dato que confunde es la potencia: los VA no son vatios. Un SAI de 700 VA suele dar unos 400 W, y esa es la cifra que hay que comparar con lo que consumen tus equipos. Los minutos de autonomía dependen de la carga: con un router y un NAS puede aguantar media hora; con un PC de sobremesa, unos pocos minutos. Revisa también cuántos enchufes van protegidos con batería y si tiene USB para que el ordenador o el NAS se apaguen solos.$q$),
('sistemas-de-sonido',$q$Receptores AV y amplificadores HiFi$q$,$q$Receptores AV y amplificadores HiFi$q$,null,$q$Un receptor AV es el centro de un cine en casa: recibe la imagen y el sonido por HDMI, decodifica Dolby Atmos o DTS:X y mueve cinco, siete o más altavoces. Un amplificador estéreo hace menos cosas, pero las hace muy bien: dos canales para escuchar música con unos buenos altavoces.

En los receptores, compara la potencia real por canal (medida con todos los canales funcionando, no con uno solo), el número de entradas HDMI 2.1 si tienes una consola actual y si calibra el sonido a la sala de forma automática. En los amplificadores, fíjate en la potencia con la impedancia de tus altavoces y en si necesitas entrada de phono para un tocadiscos.$q$),
('comederos-automaticos',$q$Comederos automáticos para gatos y perros$q$,$q$Comederos automáticos para gatos y perros$q$,null,$q$Un comedero automático reparte la comida de tu gato o tu perro a las horas que programes, aunque no estés en casa. Los más sencillos funcionan con un temporizador; los inteligentes se manejan desde el móvil, avisan si el depósito se vacía y algunos llevan cámara para ver si ha comido.

Lo más importante es la fiabilidad: que no se atasque con el tamaño de tu pienso y que siga dando de comer si se va la luz o el WiFi, por eso conviene que admita pilas de respaldo y guarde la programación. Mira después la capacidad del depósito, el tamaño mínimo de ración y si el cuenco y la tolva se pueden lavar.$q$)
) as v(slug,h1,t,d,i) where c.slug=v.slug;

insert into public.subcategories (category_id,name,slug,h1,seo_title,seo_description,intro,has_page,display_order)
select c.id,v.name,v.slug,v.h1,v.t,v.d,v.i,(v.i is not null),v.o from (values
('smart-home',$q$Iluminación inteligente$q$,'iluminacion-inteligente',$q$Bombillas inteligentes, tiras LED y lámparas WiFi$q$,$q$Bombillas inteligentes WiFi y tiras LED$q$,$q$Bombillas inteligentes E27 y GU10, tiras LED y lámparas WiFi: cuáles funcionan sin hub, cuáles con Alexa, Google o Matter y qué luz dan de verdad.$q$,$q$Las bombillas inteligentes son la forma más fácil de empezar con la domótica: se enroscan en el casquillo de siempre y se controlan desde el móvil o con la voz. Aquí también tienes tiras LED, lámparas de pie y luces con sensor de movimiento para armarios y pasillos.

Antes de comprar, comprueba el casquillo (E27, E14 o GU10), si es solo blanco regulable o RGB de colores y si se conecta por WiFi directamente o necesita un hub Zigbee. Si usas Alexa, Google Home o HomeKit, mira que sea compatible o que lleve Matter.$q$,1),
('smart-home',$q$Termostatos inteligentes$q$,'termostatos-inteligentes',$q$Termostatos inteligentes y cabezales termostáticos WiFi$q$,$q$Termostatos inteligentes WiFi para casa$q$,$q$Termostatos WiFi para caldera, cabezales para radiadores y sensores de temperatura: con qué calderas funcionan, si piden hub y cómo se programan.$q$,$q$Un termostato inteligente programa la calefacción desde el móvil, la apaga cuando sales de casa y la enciende antes de que llegues. Es el aparato de domótica que más se nota en la factura.

Hay dos formas de hacerlo. El termostato de pared sustituye al que ya controla la caldera, y conviene revisar antes cómo se conecta tu caldera (contacto libre de tensión u OpenTherm). Los cabezales termostáticos se ponen en cada radiador y permiten una temperatura distinta en cada habitación. También incluimos termómetros WiFi para vigilar la temperatura y la humedad.$q$,2),
('smart-home',$q$Enchufes inteligentes$q$,'enchufes-inteligentes',$q$Enchufes inteligentes WiFi con medidor de consumo$q$,$q$Enchufes inteligentes WiFi con medidor$q$,$q$Enchufes inteligentes de interior y exterior: cuáles miden el consumo, cuántos amperios aguantan y si funcionan con Alexa, Google Home o HomeKit.$q$,$q$Un enchufe inteligente convierte cualquier aparato en uno conectado: lo enciendes y lo apagas desde el móvil, con la voz o a una hora fija. Los que tienen medidor de consumo te dicen, además, cuánto gasta la lavadora, el termo o lo que se queda en espera.

Fíjate en la intensidad máxima: para un calefactor o un termo necesitas 16 A, no 10. Comprueba también si es para exterior (con protección IP44 o superior) y con qué asistente funciona.$q$,3),
('smart-home',$q$Asistentes de voz y control$q$,'asistentes-de-voz',$q$Altavoces con Alexa, pantallas y mandos domóticos$q$,$q$Altavoces con Alexa y mandos domóticos$q$,$q$Echo Dot, Echo Hub y mandos para controlar la domótica de casa: qué hace cada uno, cuáles hacen de hub Zigbee o Matter y cuál conviene para empezar.$q$,$q$Un altavoz con Alexa o una pantalla de control es lo que une todos los aparatos de domótica: desde ahí enciendes luces, bajas persianas o programas rutinas con la voz o con un toque.

Antes de elegir, mira si el dispositivo hace de hub (algunos Echo integran Zigbee, Thread o Matter y evitan comprar un puente aparte) y si quieres pantalla para ver las cámaras y controlarlo todo de un vistazo. Si no quieres hablarle a un altavoz, un mando físico también puede gobernar decenas de aparatos.$q$,4),
('smart-home',$q$Robots aspiradores$q$,'robots-aspiradores',null,null,null,null,5),
('smart-home',$q$Persianas inteligentes$q$,'persianas-inteligentes',null,null,null,null,6),
('smart-home',$q$Difusores de aroma$q$,'difusores-de-aroma',null,null,null,null,7),
('baterias-y-energia',$q$Estaciones de energía portátiles$q$,'estaciones-de-energia',$q$Estaciones de energía portátiles y generadores solares$q$,$q$Estaciones de energía portátiles$q$,$q$Estaciones de energía de 88 a 6.144 Wh comparadas por capacidad real, potencia de salida, batería LiFePO4 y si sirven como SAI en un apagón.$q$,$q$Una estación de energía portátil (también llamada generador solar cuando se vende con panel) es una batería grande con enchufes de 230 V, USB y salida de 12 V. Sirve para acampar, para la furgoneta y para aguantar un apagón en casa sin el ruido ni los humos de un generador de gasolina.

Compara primero la capacidad en Wh, que marca cuánto dura, y después la potencia de salida en W, que marca qué puedes enchufar. Las baterías LiFePO4 aguantan muchos más ciclos. Si la quieres para los cortes de luz, mira que tenga función SAI y cuánto tarda en conmutar.$q$,1),
('baterias-y-energia',$q$Power banks$q$,'power-banks',$q$Power banks y baterías externas para móvil y portátil$q$,$q$Power banks y baterías externas$q$,$q$Power banks de 10.000 a 27.000 mAh: cuántos vatios dan por USB-C, si cargan un portátil, si se pueden llevar en el avión y cuántas cargas salen de verdad.$q$,$q$Un power bank o batería externa carga el móvil, los auriculares o el portátil cuando no tienes un enchufe cerca. Los de 10.000 mAh caben en el bolsillo y dan para una carga y media o dos de un móvil; los de 20.000 o 25.000 mAh ya pueden con un portátil.

Más que los mAh, mira la potencia por USB-C: 20 W bastan para un móvil, pero un portátil necesita 45, 65 o 100 W. En el avión, las baterías de hasta 100 Wh (unos 27.000 mAh) pueden ir en cabina sin pedir permiso a la aerolínea. Fíjate también en si trae cables integrados y una pantalla con el porcentaje real.$q$,2),
('baterias-y-energia',$q$Paneles solares$q$,'paneles-solares',$q$Paneles solares portátiles y de 12 V$q$,$q$Paneles solares portátiles y de 12 V$q$,$q$Paneles solares plegables para cargar el móvil o una estación de energía, y paneles de 12 V para caravanas y cámaras: vatios reales, conectores y controlador.$q$,$q$Los paneles solares portátiles recargan una estación de energía, un power bank o el móvil con la luz del sol. Los plegables se llevan en la mochila o en la furgoneta; los rígidos de 12 V se instalan en una caravana, una caseta o junto a una cámara de vigilancia.

Los vatios anunciados son los de laboratorio: en la práctica, un panel rinde bastante menos según la orientación, las nubes y la temperatura. Comprueba que el conector y el voltaje encajan con tu batería o estación, y si hace falta un controlador de carga entre medias.$q$,3),
('baterias-y-energia',$q$Accesorios$q$,'accesorios',null,null,null,null,4),
('almacenamiento',$q$NAS$q$,'nas',$q$NAS para casa: servidores de 1, 2 y 4 bahías$q$,$q$NAS para casa de 1, 2 y 4 bahías$q$,$q$NAS Synology, QNAP, UGREEN y TerraMaster comparados por bahías, procesador, RAM y red de 2,5 GbE. Cuál basta para fotos y copias y cuál aguanta Plex.$q$,$q$Un NAS es un pequeño servidor que se conecta al router y guarda los archivos de toda la casa: las fotos del móvil, las copias de seguridad de los ordenadores y las películas para ver en la tele. Es como tener tu propia nube, sin cuotas mensuales.

El número de bahías decide cuántos discos caben: con dos ya puedes guardar cada archivo por duplicado y no perder nada si se rompe uno. El procesador y la RAM deciden si podrá convertir vídeo con Plex o Jellyfin, o mover contenedores Docker. Y la red de 2,5 GbE se nota al copiar archivos grandes. En casi todos, los discos se compran aparte.$q$,1),
('almacenamiento',$q$Discos duros para NAS$q$,'discos-para-nas',$q$Discos duros para NAS: CMR y funcionamiento 24/7$q$,$q$Discos duros para NAS CMR y 7200 rpm$q$,$q$Seagate IronWolf y WD Red Plus para NAS: por qué conviene CMR y no SMR, qué cambia entre 5400 y 7200 rpm y qué garantía y horas de uso cubren.$q$,$q$Los discos duros para NAS están hechos para funcionar las 24 horas, junto a otros discos y con vibraciones constantes. Por eso no conviene poner en un NAS un disco de sobremesa cualquiera.

La clave es la tecnología de grabación: los discos CMR mantienen la velocidad al reconstruir un RAID, mientras que los SMR pueden ralentizarlo mucho o incluso hacerlo fallar. Las gamas WD Red Plus y Seagate IronWolf son CMR. Después elige entre unas 5400 rpm (más silencio y menos consumo) y 7200 rpm (más velocidad), y revisa la garantía.$q$,2),
('almacenamiento',$q$Discos duros externos$q$,'discos-duros-externos',$q$Discos duros externos USB para copias y consolas$q$,$q$Discos duros externos USB$q$,$q$Discos duros externos de 500 GB a 6 TB para copias de seguridad, portátil o consola: velocidad real por USB, cifrado por hardware y qué tamaño compensa.$q$,$q$Un disco duro externo es la forma más sencilla de hacer copias de seguridad o ampliar el espacio de un portátil o una consola. Se conecta por USB, no necesita alimentación aparte y cabe en un bolsillo.

Los discos mecánicos dan mucha capacidad por poco dinero, pero se quedan en unos 100-150 MB/s y no llevan bien los golpes. Si buscas velocidad o resistencia, mira los SSD externos. Fíjate también en si incluye cifrado por hardware y en el conector, USB-A o USB-C.$q$,3),
('almacenamiento',$q$SSD$q$,'ssd',$q$SSD internos y externos: SATA, NVMe y USB-C$q$,$q$SSD internos y externos$q$,$q$SSD SATA para dar vida a un portátil antiguo y SSD externos USB-C: velocidad sostenida, caché SLC, DRAM y qué formato admite tu equipo.$q$,$q$Un SSD es el cambio que más se nota en un ordenador: arranca en segundos y abre los programas al instante. Los SSD SATA de 2,5 pulgadas sustituyen al disco duro de un portátil o un sobremesa antiguo; los M.2 NVMe son mucho más rápidos pero necesitan una ranura compatible; y los SSD externos USB-C sirven para mover archivos grandes o trabajar con vídeo.

Las cifras de la caja son picos. Lo que separa un SSD bueno de uno barato es cómo rinde cuando se acaba la caché SLC y si lleva DRAM. Lo explicamos en las guías de abajo.$q$,4),
('proyectores',$q$Proyectores 4K$q$,'proyectores-4k',$q$Proyectores 4K para cine en casa$q$,$q$Proyectores 4K para casa$q$,$q$Proyectores 4K de BenQ, Epson y XGIMI comparados por lúmenes ANSI reales, resolución por desplazamiento de píxel, tiro corto y contraste.$q$,$q$Un proyector 4K da una imagen de 100 pulgadas o más con detalle de cine, y es la alternativa a una tele enorme para el salón. Aquí tienes los modelos que muestran 4K de verdad, no solo los que aceptan la señal.

Casi todos los proyectores 4K domésticos usan desplazamiento de píxel (como el XPR de Texas Instruments o el 4K PRO-UHD de Epson) para llegar a esa resolución, y el resultado es muy bueno. Compara el brillo en lúmenes ANSI o ISO, el contraste y la distancia: un modelo de tiro corto da una pantalla grande a poco más de un metro de la pared.$q$,1),
('proyectores',$q$Proyectores Full HD$q$,'proyectores-full-hd',$q$Proyectores Full HD 1080p para casa$q$,$q$Proyectores Full HD 1080p con WiFi$q$,$q$Proyectores 1080p nativos con WiFi, Bluetooth y apps: lúmenes ANSI reales, enfoque automático, si traen Netflix oficial y cuánto ruido hacen.$q$,$q$Un proyector Full HD es el punto de equilibrio para ver películas y series en casa: resolución nativa 1080p, apps integradas y un precio muy por debajo de los 4K.

Fíjate en que sea 1080p nativo y no solo «compatible con 1080p». Compara el brillo en lúmenes ANSI, no los lúmenes sin apellido de la caja. El enfoque automático y la corrección trapezoidal ahorran tiempo cada vez que lo mueves. Y si quieres Netflix, comprueba que la app es oficial: en muchos proyectores baratos no lo es y no funciona bien.$q$,2),
('proyectores',$q$Mini proyectores$q$,'mini-proyectores',$q$Mini proyectores portátiles$q$,$q$Mini proyectores portátiles$q$,$q$Mini proyectores con Android TV y apps: lúmenes ANSI reales, tamaño de imagen útil, sonido y si traen Netflix oficial o una copia que falla.$q$,$q$Un mini proyector es pequeño, ligero y se lleva de una habitación a otra o de viaje. Sirve para ver una película en el techo del dormitorio, para una noche de cine en el jardín o para que los niños vean dibujos en grande.

Su punto débil es el brillo: con 200 o 250 lúmenes ANSI necesitas oscuridad y una imagen de 60 a 80 pulgadas para que se vea bien. Mira si lleva un sistema con apps oficiales, si tiene batería o va siempre enchufado y cómo suena el altavoz, porque muchas veces habrá que añadir uno.$q$,3),
('proyectores',$q$Pantallas de proyección$q$,'pantallas-de-proyeccion',$q$Pantallas de proyección de 72 a 120 pulgadas$q$,$q$Pantallas de proyección de 72 a 120 pulgadas$q$,$q$Pantallas para proyector manuales, con trípode, plegables y de doble cara: tamaño, formato 16:9 y si se pueden lavar y usar en el exterior.$q$,$q$Una pantalla de proyección mejora la imagen frente a una pared: refleja mejor la luz, tiene un blanco uniforme y bordes oscuros que ayudan a percibir el contraste. Las hay manuales que se enrollan en la pared, con trípode para montarlas donde quieras y plegables de tela para el jardín.

Elige el tamaño según la distancia a la que te sientas, y el formato 16:9 si es para películas. Las de doble cara permiten proyectar desde detrás, y las de tela lavable llevan mejor el uso en exterior.$q$,4),
('streaming',$q$Webcams$q$,'webcams',$q$Webcams 1080p y 4K para PC y streaming$q$,$q$Webcams 1080p y 4K para PC$q$,$q$Webcams Logitech, Insta360, EMEET y más comparadas por cómo se ven con poca luz, enfoque automático, micrófono y si de verdad graban a 60 fps.$q$,$q$Una buena webcam se nota en cada videollamada y en cada directo. Aquí las comparamos por cómo se ven con la luz de una habitación normal, que es donde la mayoría falla.

La resolución dice menos de lo que parece: una 1080p con buen sensor se ve mejor que una 4K barata. Mira el enfoque automático, el campo de visión (los gran angulares sirven para salas, no para una persona) y si da 60 fps a la resolución que necesitas. Las de seguimiento por IA te encuadran solas si te mueves. Y si vas a hablar mucho, un micrófono aparte sonará mejor que el de la webcam.$q$,1),
('streaming',$q$Micrófonos$q$,'microfonos',$q$Micrófonos USB, dinámicos y de solapa inalámbricos$q$,$q$Micrófonos USB y de solapa inalámbricos$q$,$q$Micrófonos USB para podcast y streaming, dinámicos XLR y de solapa inalámbricos para el móvil: cómo suena la voz, ruido de fondo y conexión.$q$,$q$El micrófono es lo que más mejora un directo, un pódcast o una videollamada, más que la cámara. Aquí tienes tres tipos.

Los micrófonos USB de condensador se conectan al ordenador y suenan bien desde el primer minuto, pero captan todo lo que pasa en la habitación. Los dinámicos rechazan mejor el teclado y el ruido de fondo, y los que tienen salida XLR además de USB crecen contigo si algún día usas una interfaz de audio. Y los de solapa inalámbricos se enganchan a la ropa y van directos al móvil o la cámara: son los ideales para grabar vídeos.$q$,2),
('streaming',$q$Capturadoras$q$,'capturadoras',$q$Capturadoras HDMI USB para grabar y emitir$q$,$q$Capturadoras HDMI USB con passthrough$q$,$q$Capturadoras HDMI a USB para consola o cámara: resolución y fps reales de captura, passthrough 4K, retraso y si funcionan sin drivers en OBS.$q$,$q$Una capturadora HDMI pasa la imagen de una consola, una cámara u otro ordenador al PC para grabarla o emitirla en directo con OBS. Las que tienen passthrough mandan además la imagen a la tele sin retraso, para que juegues con normalidad mientras grabas.

No confundas la resolución que pasa a la tele con la que graba: muchas aceptan 4K pero capturan en 1080p. Comprueba también si van por USB 3.0, necesario para 1080p a 60 fps, si funcionan sin instalar drivers y si sirven en Mac.$q$,3),
('streaming',$q$Reproductores multimedia$q$,'reproductores-multimedia',null,null,null,null,4),
('escaner',$q$Escáneres portátiles$q$,'escaneres-portatiles',$q$Escáneres portátiles A4 y de mano$q$,$q$Escáneres portátiles A4 y de mano$q$,$q$Escáneres portátiles con alimentador y de varita: velocidad por página, si funcionan sin ordenador con tarjeta SD, batería y calidad real.$q$,$q$Un escáner portátil digitaliza documentos donde estés: en casa, en la oficina o de viaje. Los hay de dos tipos. Los de alimentación, como el Epson WorkForce ES-50 o el Brother DS-640, tragan la hoja y la escanean en segundos conectados al portátil. Los de varita se pasan a mano por encima del papel y guardan el resultado en una tarjeta microSD, sin ordenador.

Compara la velocidad por página, si escanea a doble cara y cómo se alimenta: por USB o con batería propia. Para fotos o libros, mejor un escáner plano o uno cenital.$q$,1),
('escaner',$q$Escáneres de documentos$q$,'escaneres-de-documentos',$q$Escáneres de documentos A4: planos y con alimentador$q$,$q$Escáneres de documentos A4 planos y WiFi$q$,$q$Escáneres planos A4 y con alimentador automático para casa y oficina: páginas por minuto, doble cara, WiFi y PDF con texto buscable.$q$,$q$Un escáner de documentos de sobremesa es lo que necesitas si digitalizas papeles a menudo: facturas, contratos, apuntes o el archivo de casa. Los planos, como el Canon LiDE 400 o el Epson Perfection V39 II, escanean hoja a hoja y también sirven para fotos y libros. Los de alimentador automático, como el Epson ES-C320W, escanean pilas de hojas a doble cara sin que estés delante.

Mira las páginas por minuto, si hace doble cara de una pasada, si tiene WiFi para escanear desde el móvil y si crea PDF con texto buscable (OCR).$q$,2),
('escaner',$q$Escáneres de fotos y negativos$q$,'escaneres-de-fotos-y-negativos',$q$Escáneres de fotos, negativos y diapositivas$q$,$q$Escáneres de fotos, negativos y diapositivas$q$,$q$Escáneres de película Plustek, convertidores de negativos y escáneres de fotos en papel: resolución real, Dmax, carga automática y qué sirve para cada formato.$q$,$q$Para digitalizar fotos antiguas hay que saber primero en qué formato están. Las copias en papel se escanean bien con un escáner de fotos de alimentación o con uno plano a 600 ppp. Los negativos y las diapositivas necesitan una luz que los atraviese, y un escáner plano normal no la tiene: hace falta un escáner de película o un convertidor de negativos.

Los escáneres de película, como los Plustek OpticFilm, dan la mejor calidad, con resolución real alta y buen rango dinámico (Dmax). Los convertidores tipo cámara son más rápidos y fáciles, a cambio de detalle. Aquí también tienes un visor para revisar las diapositivas antes de escanearlas.$q$,3),
('escaner',$q$Escáneres de libros$q$,'escaneres-de-libros',null,null,null,null,4),
('seguridad-inteligente',$q$Sensores y alarmas$q$,'sensores-y-alarmas',$q$Sensores de puerta, movimiento y alarmas WiFi$q$,$q$Sensores de puerta y movimiento WiFi$q$,$q$Sensores de apertura, detectores de movimiento y alarmas WiFi sin cuotas: cuáles piden hub, cuánto dura la pila y si funcionan con Alexa o Matter.$q$,$q$Los sensores de puerta y de movimiento son la base de una alarma casera sin cuotas: avisan al móvil cuando alguien abre una ventana o pasa por el pasillo, y pueden encender luces o hacer sonar una sirena.

Elige primero cómo se conectan. Los WiFi no necesitan nada más, pero gastan más pila. Los Zigbee, Thread o Matter requieren un hub y a cambio responden más rápido y duran más. Mira también si los detectores de movimiento son para interior o exterior, y si la sirena va incluida o se compra aparte.$q$,1),
('seguridad-inteligente',$q$Cámaras de vigilancia$q$,'camaras-de-vigilancia',$q$Cámaras de vigilancia WiFi para interior$q$,$q$Cámaras de vigilancia WiFi de interior$q$,$q$Cámaras WiFi de interior con giro 360°, visión nocturna y grabación en microSD: qué funciones quedan sin suscripción y cuáles van con Alexa o Google.$q$,$q$Una cámara de vigilancia WiFi para interior te deja ver la casa desde el móvil, recibir avisos de movimiento y hablar con quien esté al otro lado. Sirve para la segunda residencia, para vigilar a la mascota o como complemento de una alarma.

Mira si graba en tarjeta microSD o solo en la nube con suscripción, qué funciones se pierden si no pagas y si tiene giro motorizado para cubrir toda la habitación. La detección de personas evita un aviso por cada sombra. Y si te preocupa la privacidad, busca un modo privado que tape o gire la lente.$q$,2),
('seguridad-inteligente',$q$Cerraduras y mirillas$q$,'cerraduras-y-mirillas',null,null,null,null,3),
('cultivo-inteligente',$q$Huertos hidropónicos$q$,'huertos-hidroponicos',$q$Huertos hidropónicos de interior con luz LED$q$,$q$Huertos hidropónicos de interior con LED$q$,$q$Huertos inteligentes Click & Grow, iDOO y GOLUMUP: cuántas vainas, altura de la lámpara, consumo y si admiten semillas propias o solo cápsulas.$q$,$q$Un huerto hidropónico de interior cultiva sin tierra: las raíces están en agua con nutrientes y una lámpara LED hace de sol. Así puedes tener albahaca, lechugas o fresas en la cocina todo el año.

Cuenta las vainas que necesitas: con 6 tienes hierbas para cocinar; con 12 o más ya sacas ensaladas. La altura máxima de la lámpara limita qué plantas puedes cultivar. Y antes de comprar, mira si admite semillas propias con esponjas genéricas o te obliga a comprar cápsulas de la marca, que es donde está el gasto a la larga.$q$,1),
('cultivo-inteligente',$q$Lámparas de cultivo$q$,'lamparas-de-cultivo',$q$Lámparas LED de cultivo para plantas de interior$q$,$q$Lámparas LED de cultivo para interior$q$,$q$Lámparas de cultivo LED con trípode, pinza o panel: vatios reales frente a los anunciados, espectro completo, temporizador y altura para cada planta.$q$,$q$Una lámpara de cultivo da a las plantas de interior la luz que les falta lejos de la ventana o en invierno. Las de pinza o trípode sirven para unas pocas macetas; los paneles grandes cubren una mesa de cultivo o un armario.

Compara los vatios reales de consumo, no los «equivalentes» de la caja, y busca espectro completo si quieres que la planta crezca y florezca. El temporizador evita tener que acordarte de encenderla y apagarla, y la altura regulable permite acercar la luz según crece la planta.$q$,2),
('cultivo-inteligente',$q$Riego automático$q$,'riego-automatico',$q$Riego automático por goteo y programadores de riego$q$,$q$Riego automático por goteo y programadores$q$,$q$Kits de riego por goteo para macetas y programadores de grifo: si necesitan presión, cuántas plantas riegan, cómo se programan y qué hacer en vacaciones.$q$,$q$Un sistema de riego automático se encarga de las plantas cuando no estás o cuando se te olvida. Hay dos formas de montarlo. Los kits de goteo con bomba toman el agua de un depósito o un cubo y no necesitan grifo, así que sirven para pisos, balcones y plantas de interior. Los programadores de grifo se enroscan a la toma de agua y abren el riego a las horas que les digas.

Comprueba cuántas salidas tiene el kit, si el programador funciona con poca presión (algunos funcionan incluso a 0 bar, con el depósito en alto) y cómo se alimenta: por USB, pilas o batería.$q$,3),
('impresoras-de-etiquetas',$q$Etiquetadoras Bluetooth$q$,'etiquetadoras-bluetooth',$q$Etiquetadoras Bluetooth portátiles$q$,$q$Etiquetadoras Bluetooth portátiles$q$,$q$Etiquetadoras NIIMBOT, DYMO, SUPVAN y más que imprimen desde el móvil: ancho de etiqueta, coste de los rollos y si admiten consumibles genéricos.$q$,$q$Las etiquetadoras Bluetooth imprimen desde una app del móvil: escribes el texto, añades un icono o un código QR y la etiqueta sale en segundos. Son las más cómodas para organizar la despensa, los cables o el material de clase.

Casi todas son térmicas y muchas usan rollos con chip que identifican el tipo de etiqueta. Antes de comprar, mira el ancho máximo (de 12 a 50 mm), el precio de los rollos y si la marca admite consumibles genéricos o solo los suyos. La app también importa: algunas piden registro o tienen funciones de pago.$q$,1),
('impresoras-de-etiquetas',$q$Rotuladoras con teclado$q$,'rotuladoras',$q$Rotuladoras y etiquetadoras con teclado$q$,$q$Rotuladoras y etiquetadoras con teclado$q$,$q$Rotuladoras DYMO LetraTag y LabelManager y etiquetadoras de relieve: teclado, tipo de cinta, coste por metro y si sirven sin móvil ni ordenador.$q$,$q$Una rotuladora con teclado funciona sola, sin móvil ni ordenador: escribes en sus teclas, ves el texto en la pantalla y sale la etiqueta. Es la opción de toda la vida y sigue siendo la más rápida para unas pocas etiquetas sueltas.

Las DYMO LetraTag usan cintas de papel o plástico; las LabelManager, cintas D1 laminadas que aguantan el agua y el roce; y las manuales de relieve no necesitan ni pilas. Compara el tipo de cinta, su precio por metro y la distribución del teclado.$q$,2),
('impresoras-de-etiquetas',$q$Impresoras de etiquetas de envío$q$,'etiquetas-de-envio',$q$Impresoras de etiquetas de envío 4x6$q$,$q$Impresoras de etiquetas de envío 4x6$q$,$q$Impresoras térmicas de etiquetas de envío 4x6 (100x150 mm) para tienda online: transportistas, velocidad, USB o Bluetooth y etiquetas genéricas.$q$,$q$Si vendes por internet, una impresora de etiquetas de envío ahorra tiempo, papel y tinta: imprime directamente la etiqueta de 100x150 mm (4x6 pulgadas) que piden la mayoría de transportistas y plataformas.

Son térmicas directas, así que no gastan tinta ni tóner. Comprueba que funcionan con tu sistema operativo y tus plataformas de venta, que admiten etiquetas en rollo y en acordeón de cualquier marca, y si se conectan por USB o Bluetooth. Para volúmenes altos, una impresora industrial como la Zebra aguanta mucho más uso seguido.$q$,3),
('impresoras-de-etiquetas',$q$Impresoras de etiquetas de sobremesa$q$,'etiquetas-de-sobremesa',$q$Impresoras de etiquetas de sobremesa Brother y DYMO$q$,$q$Impresoras de etiquetas de sobremesa$q$,$q$Brother QL y DYMO LabelWriter para oficina: ancho de etiqueta, cortador automático, WiFi, impresión en rojo y negro y coste de las etiquetas.$q$,$q$Las impresoras de etiquetas de sobremesa, como las Brother QL o las DYMO LabelWriter, se conectan al ordenador y sacan etiquetas de dirección, códigos de barras o etiquetas de producto a buen ritmo. Son la elección para una oficina, un pequeño comercio o un almacén.

Fíjate en el ancho máximo (62 mm en las QL-800, 102 mm en la QL-1110), en si tienen cortador automático y conexión WiFi o de red, y en si las etiquetas tienen que ser de la marca. Algunas Brother imprimen en rojo y negro con un rollo especial.$q$,4),
('conectividad-docking',$q$Hubs y docks USB-C$q$,'hubs-usb-c',$q$Hubs USB-C y docking stations para portátil$q$,$q$Hubs USB-C y docking stations$q$,$q$Hubs y docks USB-C con HDMI 4K a 60 Hz, Ethernet y carga Power Delivery: cuántos monitores extienden de verdad y qué pasa en un MacBook.$q$,$q$Un hub USB-C añade al portátil los puertos que le faltan con un solo cable: HDMI, USB-A, lector de tarjetas, Ethernet y carga. Una docking station hace lo mismo a lo grande, pensada para dejarla fija en la mesa con dos o tres monitores.

Mira si el HDMI da 4K a 60 Hz o se queda en 30 Hz, cuántos vatios de carga pasan al portátil y cuántos monitores puede extender. En los MacBook con chip M básico, un hub con dos HDMI muestra la misma imagen en las dos pantallas; para extender hace falta DisplayLink.$q$,1),
('conectividad-docking',$q$HDMI inalámbrico$q$,'hdmi-inalambrico',$q$Transmisores HDMI inalámbricos$q$,$q$Transmisores HDMI inalámbricos 4K$q$,$q$Transmisores HDMI inalámbricos para llevar la imagen del portátil, la consola o el decodificador a la tele o el proyector: distancia real, retraso y resolución.$q$,$q$Un transmisor HDMI inalámbrico manda la imagen y el sonido de un aparato a una tele o un proyector sin tender cable. Es útil para un proyector en el techo, para presentaciones en una sala de reuniones o para ver el decodificador en otra habitación.

La distancia anunciada es en campo abierto: con paredes de por medio baja mucho. El retraso decide el uso: para presentaciones y vídeo no importa, pero para jugar se nota. Comprueba también si es 4K o 1080p de verdad y si el emisor va por HDMI o por USB-C.$q$,2),
('realidad-virtual',$q$Gafas VR$q$,'gafas-vr',$q$Gafas de realidad virtual: Meta Quest, PS VR2 y para móvil$q$,$q$Gafas VR: Meta Quest, PS VR2 y para móvil$q$,$q$Gafas de realidad virtual autónomas, para PS5 y visores para móvil: resolución por ojo, catálogo de juegos, comodidad y para qué edad tiene sentido cada una.$q$,$q$Las gafas de realidad virtual te meten dentro del juego, la película o la clase. Las autónomas, como Meta Quest 3 y 3S, funcionan solas, sin cables ni ordenador, y también hacen realidad mixta. Las PlayStation VR2 se conectan a la PS5 y dan más calidad gráfica en sus juegos. Y los visores para móvil son la opción barata para vídeos 360 y para que los niños prueben la experiencia.

Compara la resolución por ojo, el ajuste de las lentes, el catálogo de juegos y el peso. Meta recomienda sus Quest a partir de 10 años.$q$,1),
('realidad-virtual',$q$Accesorios VR$q$,'accesorios-vr',$q$Accesorios para Meta Quest 3 y 3S$q$,$q$Accesorios para Meta Quest 3 y 3S$q$,$q$Fundas de silicona para mandos, culatas de rifle y mandos Bluetooth para gafas VR: qué mejoran de verdad y cuáles son compatibles con Quest 3 y 3S.$q$,$q$Los accesorios de realidad virtual mejoran la comodidad y la experiencia de juego. Las fundas de silicona para los mandos evitan que se resbalen y los protegen de los golpes; las culatas de rifle dan estabilidad en los juegos de disparos; y los mandos Bluetooth permiten manejar los visores para móvil.

Antes de comprar, comprueba que el accesorio es compatible con tu modelo exacto: los mandos de Quest 3 y 3S son iguales, pero los de Quest 2 tienen otra forma.$q$,2),
('impresoras-portatiles',$q$Impresoras de fotos$q$,'impresoras-de-fotos',$q$Impresoras de fotos portátiles para el móvil$q$,$q$Impresoras de fotos portátiles$q$,$q$Impresoras de fotos Canon Selphy, Kodak, Zink e Instax Link: tamaño de copia, coste por foto, durabilidad y calidad frente a una cámara instantánea.$q$,$q$Una impresora de fotos portátil imprime desde el móvil las fotos que ya tienes. Hay varias tecnologías. La sublimación (Canon Selphy, Kodak) da copias de 10x15 o de tamaño tarjeta con colores duraderos. El papel Zink (Canon Zoemini) es adhesivo y no necesita tinta, aunque los colores son más apagados. Y las Instax Link imprimen en película Instax, con el aspecto de una cámara instantánea.

Compara el coste por foto, el tamaño de la copia, el tiempo de impresión y si la app deja editar antes de imprimir.$q$,1),
('impresoras-portatiles',$q$Impresoras térmicas$q$,'impresoras-termicas',$q$Impresoras térmicas portátiles sin tinta$q$,$q$Impresoras térmicas portátiles sin tinta$q$,$q$Mini impresoras térmicas Bluetooth y portátiles A4 sin tinta: para qué sirven, cuánto dura la impresión, coste del papel y si funcionan sin app.$q$,$q$Una impresora térmica portátil imprime sin tinta: calienta un papel especial que se oscurece. Las mini impresoras Bluetooth sacan notas, pegatinas y apuntes en rollos pequeños, y las A4, como la Phomemo M08F, imprimen documentos completos desde el móvil o el portátil.

Su gran ventaja es que no hay cartuchos que se sequen. A cambio, solo imprimen en blanco y negro y la impresión se va borrando con el tiempo, el calor y el sol: sirve para lo temporal, no para guardar. Mira el ancho del papel, la resolución y si la app pide registro.$q$,2),
